DROP POLICY IF EXISTS "Enable all for admin" ON clients; CREATE POLICY "Enable all for admin and client_head" ON clients FOR ALL USING (has_any_role(ARRAY['admin', 'super_admin', 'client_head'])); CREATE POLICY "Enable read for client_head on audits" ON audits FOR SELECT USING (has_any_role(ARRAY['client_head'])); CREATE POLICY "Enable read for client_head on audit_teams" ON audit_teams FOR SELECT USING (has_any_role(ARRAY['client_head'])); CREATE POLICY "Enable read for client_head on vendors" ON vendors FOR SELECT USING (has_any_role(ARRAY['client_head']));